import{e as t,ab as a,a1 as n,m as o,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [November]","description":"November 2025 updates","frontmatter":{"title":"Monthly Updates [November]","description":"November 2025 updates","date":"2025-11-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/Nov-2025.md","filePath":"posts/Nov-2025.md"}'),l={name:"posts/Nov-2025.md"};function h(d,e,p,f,m,g){const r=a("Post");return n(),o("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added the <strong><a href="https://i.ibb.co/hx97zL3W/978676.jpg" target="_blank" rel="noreferrer">AMOLED Theme</a></strong> / <a href="https://i.imgur.com/fMrnGmF.png" target="_blank" rel="noreferrer">2</a> to our site as a <a href="https://i.ibb.co/pvkfg3hC/image.png" target="_blank" rel="noreferrer">Toggle</a> / <a href="https://i.imgur.com/qF7exKw.png" target="_blank" rel="noreferrer">2</a> that can be turned on or off. Thank you to @Land for doing this.</p></li><li><p>Built an <strong><a href="https://fmhy-search.dev.zenir.tech/" target="_blank" rel="noreferrer">External Search Engine</a></strong> that should work better in most cases than the built-in VitePress search on our website.</p></li><li><p>Added a <strong><a href="https://fmhyclone.pages.dev/" target="_blank" rel="noreferrer">New Backup</a></strong> of FMHY with daily sync, hosted on GitLab. It also includes a backup of the <a href="https://fmhyapi.wispy.qzz.io/single-page" target="_blank" rel="noreferrer">raw markdown</a> page. We also added another <a href="https://a-fmhy.pages.dev/" target="_blank" rel="noreferrer">backup</a> of our website that has the aforementioned theme enabled by default.</p></li><li><p>The Space section has become a bit hard to navigate (60+ lines), so we&#39;ve split it into its <a href="https://fmhy.net/educational#space" target="_blank" rel="noreferrer">own head section</a>, with two new subsections: <a href="https://fmhy.net/educational#astronomy" target="_blank" rel="noreferrer">Astronomy</a> and <a href="https://fmhy.net/educational#spacecraft" target="_blank" rel="noreferrer">Spacecraft</a>. Astronomy covers celestial objects or phenomena in the cosmos. Spacecraft covers rockets, launches, and the ISS. The head section remains for general space-related things like NASA&#39;s website, news, etc.</p></li><li><p>Remakes / Ports in Gaming had over 80 lines and was disorganized, so we&#39;ve split it into three new sections to make it more comprehensible: <a href="https://fmhy.net/gaming#decomps-ports" target="_blank" rel="noreferrer">Decomps / Ports</a>, <a href="https://fmhy.net/gaming#remakes-recreations" target="_blank" rel="noreferrer">Remakes / Recreations</a>, and <a href="https://fmhy.net/gaming#revival-projects" target="_blank" rel="noreferrer">Revival Projects</a>. We also turned &quot;Special Interest&quot; into its own head category to organize the TOC better.</p></li><li><p>Re-ordered <a href="https://fmhy.net/reading#manga" target="_blank" rel="noreferrer">Manga Sites</a> based on poll results from our Discord. Weeb Central has moved to the #1 spot, and MangaFire + MangaNato have both been starred. Thank you to everyone who voted. <a href="https://i.ibb.co/j9Sn4hRR/image.png" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/u8zFZTX.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Cleaned up multiple Audio Streaming sections and added new ones to improve organization, including: <a href="https://fmhy.net/audio#specialty-streaming" target="_blank" rel="noreferrer">Specialty</a>, <a href="https://fmhy.net/audio#genre-specific-streaming" target="_blank" rel="noreferrer">Genre-Specific</a>, <a href="https://fmhy.net/audio#radio-directories" target="_blank" rel="noreferrer">Radio Directories</a>, and <a href="https://fmhy.net/audio#lofi-radio" target="_blank" rel="noreferrer">Lofi Radio</a>. <a href="https://github.com/fmhy/edit/pull/4128#issuecomment-3476036920" target="_blank" rel="noreferrer">Before vs. After</a>. Thank you to @AnarchyDR for this work.</p></li><li><p>Updated the <a href="https://fmhy.net/audio" target="_blank" rel="noreferrer">Audio Streaming</a> Table of Contents to make it less cluttered and easier to navigate. <a href="https://i.ibb.co/0yJbh03H/234243.jpg" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/fhgqKzb.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Cleaned up <a href="https://fmhy.net/gaming#browser-emulators" target="_blank" rel="noreferrer">Browser Emulators</a>, fixed labels, removed dead sites, and moved any sites only serving as EmulatorJS / NeptunJS frontends to storage. <a href="https://i.ibb.co/LXdhcDFD/Untitled.png" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/W9x8jY4.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>We removed the &quot;No Torrenting&quot; label from Proton VPN as you can now set it up with an OpenVPN config that allows you to torrent for free. Note that these expire and must be regenerated periodically. The guide is listed next to <a href="https://fmhy.net/privacy#vpn" target="_blank" rel="noreferrer">Proton</a>. TY to Wispy and others for figuring this out.</p></li><li><p>Added a <a href="https://fmhy.net/gaming#tetris" target="_blank" rel="noreferrer">Tetris</a> section to Gaming.</p></li><li><p>Fixed messy formatting in Game Optimization. <a href="https://i.ibb.co/Vc99kJhh/image.png" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/HRPUwL3.png" target="_blank" rel="noreferrer">2</a>.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/file-tools#download-managers" target="_blank" rel="noreferrer">AB Download Manager</a> in Download Managers. Open-source, fast, cross-platform, supports resumable downloads, and has an active dev team.</p></li><li><p>Bumped <a href="https://fmhy.net/gaming#rom-sites" target="_blank" rel="noreferrer">CrocDB</a> to the new #1 spot over Myrient in ROM sites. Croc covers multiple sites, has a better UI, and a new &quot;rompack&quot; feature.</p></li><li><p>Starred <a href="https://fmhy.net/video#torrent-apps" target="_blank" rel="noreferrer">PlayTorrio</a> in Torrent Streaming Apps. A feature-rich new client with addons similar to Stremio (like Torrentio), Jackett integration, and Debrid support.</p></li><li><p>Starred <a href="https://fmhy.net/ai#specialized-chatbots" target="_blank" rel="noreferrer">NotebookLM</a> in Specialized Chatbots. Excellent for document-based chatting and note-taking. It handles audio/video overviews well and can generate quizzes and flashcards.</p></li><li><p>Starred <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">Anidap</a> in Anime Streaming. Features a nice UI and utilizes unique, fast hosts.</p></li><li><p>Starred <a href="https://fmhy.net/video#live-tv" target="_blank" rel="noreferrer">PlayTorrio IPTV</a> in Live TV / Sports. Fast streams, huge library, and solid quality. Note that Darkness TV is the original; PlayTorrio has improved the UI.</p></li><li><p>Starred <a href="https://fmhy.net/linux-macos#linux-gaming" target="_blank" rel="noreferrer">Heroic Games Launcher</a> in Linux Gaming. An excellent launcher for Epic, GOG, and Prime games; currently better maintained than Lutris.</p></li><li><p>Starred <a href="https://fmhy.net/reading#curated-recommendations" target="_blank" rel="noreferrer">ComicBookRoundup</a> in Reading Recommendations. A comic-focused review and rating aggregator, similar to Metacritic.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#rom-sites" target="_blank" rel="noreferrer">Ziperto</a> in ROM Sites. A long-standing site with a massive library and fast hosts.</p></li><li><p>Starred <a href="https://fmhy.net/video#live-sports" target="_blank" rel="noreferrer">Sportsbite</a> in Live Sports. An aggregator with numerous hosts, a clean UI, and coverage for most major events.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed DramaGo as they seem to have shut down.</p></li><li><p>Unstarred Character.AI due to the ongoing removal of popular characters and user dissatisfaction with increasing restrictions/filters.</p></li></ul>',9))])}const b=t(l,[["render",h]]);export{u as __pageData,b as default};
